from collections import namedtuple

Match = namedtuple('Match', ['queryIdx', 'trainIdx', 'distance'])


def lowes_ratio_test(knn_matches, ratio=0.75):
    good = []
    for pair in knn_matches:
        if len(pair) < 2:
            continue
        m, n = pair[0], pair[1]
        if m.distance < ratio * n.distance:
            good.append(m)
    return good
